quickStart:
-- Inline progress bar
SELECT tp_bar(0.75) AS progress;

-- Sparkline of values
SELECT tp_sparkline([45.2, 47.1, 46.8, 49.3, 52.1, 48.7]) AS prices;

-- Density plot
SELECT tp_density([1, 2, 3, 4, 5, 4, 3, 2, 1]) AS density;

-- QR code (ASCII / emoji)
SELECT tp_qr('https://query.farm');
